/**
 * Compact storage for the bundled canon unit lists (src/data/canon/*.json),
 * generated by tools/convert-megamek.ts from MegaMek Data (CC BY-NC-SA 4.0).
 */
import type { Location, MechDesign, MountedItem, OmniConfiguration } from '../rules/types';
import type { FighterDesign, FighterLocation } from '../rules/fighter';
import { newFighterUid } from '../rules/fighter';
import type { VehicleDesign, VehicleLocation } from '../rules/vehicle';
import { newUid } from '../rules/edit';
import { newVehicleUid } from '../rules/vehicle';
import type { SupportVehicleDesign, SVLocation } from '../rules/support';
import { newSupportUid } from '../rules/support';

/** One catalog entry: summary fields for browsing plus the encoded design. */
export interface CanonEntry {
  /** Display name: chassis and model. */
  n: string;
  /** Tonnage. */
  t: number;
  tb: 'IS' | 'Clan';
  era: MechDesign['era'];
  /** Introduction year. */
  y: number;
  /** Kind: 'mech', 'omni:<configurations>' or a vehicle motive type. */
  k: string;
  /** Battle Value as calculated by MechForger. */
  bv: number;
  /** Passes MechForger's validation without errors. */
  ok: boolean;
  /** Weight adds up to exactly the tonnage under MechForger's tables. */
  w: boolean;
  src?: string;
  mul?: number;
  d: unknown;
}

/** Item: [equipmentId, location, flags] where flags may contain R (rear) and P (pod). */
type EncodedItem = [string, string | null, string?];

const encItem = (e: { equipmentId: string; location: string | null; rear?: boolean; pod?: boolean }): EncodedItem => {
  const flags = `${e.rear ? 'R' : ''}${e.pod ? 'P' : ''}`;
  return flags ? [e.equipmentId, e.location, flags] : [e.equipmentId, e.location];
};

const decMechItem = ([equipmentId, location, flags = '']: EncodedItem): MountedItem => {
  const item: MountedItem = { uid: newUid(), equipmentId, location: location as Location | null };
  if (flags.includes('R')) item.rear = true;
  if (flags.includes('P')) item.pod = true;
  return item;
};

export function encodeMech(d: MechDesign): unknown {
  return {
    ...d,
    equipment: d.equipment.map(encItem),
    omni: d.omni && {
      active: d.omni.active,
      configurations: d.omni.configurations.map((c) => ({ ...c, pod: c.pod.map(encItem) })),
    },
  };
}

interface EncodedMech extends Omit<MechDesign, 'equipment' | 'omni'> {
  equipment: EncodedItem[];
  omni: { active: number; configurations: (Omit<OmniConfiguration, 'pod'> & { pod: EncodedItem[] })[] } | null;
}

export function decodeMech(raw: unknown): MechDesign {
  const r = raw as EncodedMech;
  return {
    ...r,
    equipment: r.equipment.map(decMechItem),
    omni: r.omni && {
      active: r.omni.active,
      configurations: r.omni.configurations.map((c) => ({ ...c, pod: c.pod.map(decMechItem) })),
    },
  };
}

export function encodeVehicle(d: VehicleDesign): unknown {
  return { ...d, equipment: d.equipment.map(encItem) };
}

export function decodeVehicle(raw: unknown): VehicleDesign {
  const r = raw as Omit<VehicleDesign, 'equipment'> & { equipment: EncodedItem[] };
  return {
    ...r,
    equipment: r.equipment.map(([equipmentId, location]) => ({
      uid: newVehicleUid(), equipmentId, location: location as VehicleLocation | null,
    })),
  };
}

export function encodeSupport(d: SupportVehicleDesign): unknown {
  return { ...d, equipment: d.equipment.map(encItem) };
}

export function decodeSupport(raw: unknown): SupportVehicleDesign {
  const r = raw as Omit<SupportVehicleDesign, 'equipment'> & { equipment: EncodedItem[] };
  return {
    ...r,
    equipment: r.equipment.map(([equipmentId, location]) => ({
      uid: newSupportUid(), equipmentId, location: location as SVLocation | null,
    })),
  };
}

export function encodeFighter(d: FighterDesign): unknown {
  return { ...d, equipment: d.equipment.map((e) => (e.rear ? [e.equipmentId, e.location, 'R'] : [e.equipmentId, e.location])) };
}

export function decodeFighter(raw: unknown): FighterDesign {
  const r = raw as Omit<FighterDesign, 'equipment'> & { equipment: EncodedItem[] };
  return {
    ...r,
    equipment: r.equipment.map(([equipmentId, location, flags = '']) => ({
      uid: newFighterUid(), equipmentId, location: location as FighterLocation | null, ...(flags.includes('R') ? { rear: true } : {}),
    })),
  };
}
